/** Narrow any string to a supported Locale, falling back to the default. */
export function resolveLocale(input: string | undefined | null): Locale {
  if (!input) return DEFAULT_LOCALE;
  const base = input.trim().toLowerCase().split("-")[0];
  return (SUPPORTED_LOCALES as readonly string[]).includes(base ?? "")
    ? (base as Locale)
    : DEFAULT_LOCALE;
}

/**
 * Pick the best supported locale from an HTTP `Accept-Language` header, honoring
 * the client's quality (q) ordering. Used by the Download Center auto-language.
 */
export function resolveFromAcceptLanguage(header: string | undefined | null): Locale {
  if (!header) return DEFAULT_LOCALE;
  const ranked = header
    .split(",")
    .map((part) => {
      const [tag, ...params] = part.trim().split(";");
      const q = params.find((p) => p.startsWith("q="));
      const quality = q ? Number.parseFloat(q.slice(2)) : 1;
      return { tag: (tag ?? "").toLowerCase(), quality: Number.isNaN(quality) ? 0 : quality };
    })
    .sort((a, b) => b.quality - a.quality);

  for (const { tag } of ranked) {
    const base = tag.split("-")[0] ?? "";
    if ((SUPPORTED_LOCALES as readonly string[]).includes(base)) return base as Locale;
  }
  return DEFAULT_LOCALE;
}

function interpolate(template: string, vars: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, k: string) => (k in vars ? String(vars[k]) : `{${k}}`));
}

/** Translate a key for a locale, with {placeholder} interpolation. Falls back to EN if key missing. */
export function translate(
  locale: Locale,
  key: MessageKey,
  vars: Record<string, string | number> = {},
): string {
  const catalog = (CATALOGS[locale] ?? CATALOGS[DEFAULT_LOCALE]) as Record<string, string>;
  const template = catalog[key] ?? (CATALOGS.en as Record<string, string>)[key] ?? key;
  return interpolate(template, vars);
}

/** A bound translator for a single locale (convenience for UI layers). */
export function createTranslator(locale: Locale) {
  return (key: MessageKey, vars?: Record<string, string | number>) => translate(locale, key, vars);
}

const INTL_LOCALE: Record<Locale, string> = {
  en: "en-US",
  tr: "tr-TR",
  es: "es-ES",
  fr: "fr-FR",
  de: "de-DE",
  it: "it-IT",
  pt: "pt-BR",
  nl: "nl-NL",
  pl: "pl-PL",
  cs: "cs-CZ",
  ru: "ru-RU",
  uk: "uk-UA",
  ar: "ar-SA",
  he: "he-IL",
  hi: "hi-IN",
  ja: "ja-JP",
  ko: "ko-KR",
  "zh-Hans": "zh-CN",
  "zh-Hant": "zh-TW",
  vi: "vi-VN",
};

export function formatNumber(locale: Locale, value: number): string {
  return new Intl.NumberFormat(INTL_LOCALE[locale]).format(value);
}

export function formatCurrency(locale: Locale, value: number, currency: string): string {
  return new Intl.NumberFormat(INTL_LOCALE[locale], { style: "currency", currency }).format(value);
}

export function formatDate(locale: Locale, date: Date): string {
  return new Intl.DateTimeFormat(INTL_LOCALE[locale], { dateStyle: "long" }).format(date);
}

/**
 * Format a time in locale-appropriate style.
 * Uses 24-hour format for most locales, 12-hour for English.
 */
export function formatTime(locale: Locale, date: Date): string {
  return new Intl.DateTimeFormat(INTL_LOCALE[locale], {
    hour: "numeric",
    minute: "2-digit",
    hour12: locale === "en",
  }).format(date);
}

// ── Unit Formatting ─────────────────────────────────────────────────────────

export type UnitSystem = "metric" | "imperial";

/** Default unit system per locale. */
const LOCALE_UNIT_SYSTEM: Record<Locale, UnitSystem> = {
  en: "imperial",
  tr: "metric",
  es: "metric",
  fr: "metric",
  de: "metric",
  it: "metric",
  pt: "metric",
  nl: "metric",
  pl: "metric",
  cs: "metric",
  ru: "metric",
  uk: "metric",
  ar: "metric",
  he: "metric",
  hi: "metric",
  ja: "metric",
  ko: "metric",
  "zh-Hans": "metric",
  "zh-Hant": "metric",
  vi: "metric",
};

export function getUnitSystem(locale: Locale): UnitSystem {
  return LOCALE_UNIT_SYSTEM[locale];
}

/** Format temperature in the locale-appropriate unit (°C or °F). */
export function formatTemperature(locale: Locale, celsius: number): string {
  const system = LOCALE_UNIT_SYSTEM[locale];
  if (system === "imperial") {
    const f = Math.round((celsius * 9) / 5 + 32);
    return `${f}°F`;
  }
  return `${Math.round(celsius)}°C`;
}

/** Format distance in locale-appropriate unit (km or mi). */
export function formatDistance(locale: Locale, meters: number): string {
  const system = LOCALE_UNIT_SYSTEM[locale];
  if (system === "imperial") {
    const miles = meters / 1609.34;
    return miles >= 1 ? `${miles.toFixed(1)} mi` : `${Math.round(meters * 3.281)} ft`;
  }
  return meters >= 1000 ? `${(meters / 1000).toFixed(1)} km` : `${Math.round(meters)} m`;
}

/** Format weight in locale-appropriate unit (kg or lb). */
export function formatWeight(locale: Locale, kg: number): string {
  const system = LOCALE_UNIT_SYSTEM[locale];
  if (system === "imperial") {
    return `${(kg * 2.205).toFixed(1)} lb`;
  }
  return `${kg.toFixed(1)} kg`;
}

